<script setup lang="ts">import{ref}from'vue';import{client,errorMessage}from'../../../../shared/api/client';const file=ref<File>();const busy=ref(false);const message=ref('');async function restore(){if(!file.value)return;busy.value=true;message.value='';try{const form=new FormData();form.set('file',file.value,file.value.name);const response=await client.POST('/api/admin/setup/restore',{body:{file:file.value.name},bodySerializer:()=>form});if(!response.response.ok)throw new Error('恢复包验证失败');message.value='恢复包已验证并暂存。请重启程序以应用恢复。'}catch(cause){message.value=errorMessage(cause)}finally{busy.value=false}}</script>
<template><section class="mt-8 border-t border-border pt-6"><h2 class="font-semibold">从备份恢复</h2><p class="mt-2 text-sm text-muted">仅在创建超级管理员之前可用。恢复会在下次启动时应用，并保留恢复前目录。</p><input type="file" accept=".gz,application/gzip" class="mt-4" @change="file=($event.target as HTMLInputElement).files?.[0]"><button type="button" class="nw-button mt-4" :disabled="busy||!file" @click="restore">验证并准备恢复</button><p class="mt-2 text-sm">{{ message }}</p></section></template>
